//! The P2.9 test vectors: generated by the CPU oracle, committed in `kernels/testvectors/`, and
//! read back by every backend's parity tests (P2.10, P2.11, P2.12, P5.2) and by
//! `python/hsn/kernels/testvectors.py`.
//!
//! One file per (size, op), `<size>_<op>.safetensors`, holds every tensor of the op named as the
//! header's arguments ([`Op::tensors`]): the forward inputs, the forward outputs (including the
//! saved `hidden_saved` / `h_old_saved`), the cotangents that seed the backward, and the
//! gradients. Float tensors are F32, index tensors I32, little-endian. `MANIFEST.json` lists every
//! file with its op, size, dimensions, byte count and SHA-256, plus the spec version and the
//! tolerances.
//!
//! How the values are made:
//!
//! * Inputs and cotangents come from a SplitMix64 stream seeded by the FNV-1a hash of
//!   `"hsn-p2.9/<size>/<op>"`. Every float is an integer in [−128, 128] times a power of two
//!   (about `1/√fan_in` for weights), so it is exact in f16 and bf16 as well as f32: the
//!   half-precision parity tests of P2.10/P2.11 feed the same inputs and measure only their own
//!   rounding. Gates are `k/256` with `k ∈ [1, 255]`, edge weights `k/256` with `k ∈ [13, 243]`.
//! * Outputs and gradients are computed by [`CpuBackend`] in **f64** on the exactly widened
//!   inputs and rounded once to f32: the fp32 reference every implementation is compared with.
//! * The structure exercises the edge cases: `gather_concat` and `csr_messages` repeat a cell in
//!   the last row (the host maps padded slots to cell 0, so repeats are real); the `odd` graph has
//!   in-degrees 0 to 5 with empty rows (one of them selected); the gated update has padded slots
//!   holding a duplicate of a valid cell, −1, `N` and `i32::MAX` (never read); the `odd`
//!   grouped MLP leaves unit 3 without pairs (zero gradients).
//!
//! The bytes depend on nothing but this code: the oracle's maths is pure Rust (see
//! [`crate::cpu::math`]) and the JSON keys are sorted, so regeneration is byte-identical on every
//! platform. Regenerate (and bless) with
//! `HSN_WRITE_TESTVECTORS=1 cargo test -p hsn-kernels --test oracle vectors_regenerate_deterministically`.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde_json::{Value, json};

use crate::spec::{self, CellDims, Kind, Op, Role, SPEC_VERSION, Size, UnitDims};
use crate::{
    Backend, CpuBackend, CsrMessages, CsrMessagesBwd, DType, GatedDeltaUpdate, GatedDeltaUpdateBwd,
    GatherConcat, GatherConcatBwd, GroupedUnitMlpBwd, GroupedUnitMlpFwd, TensorMut, TensorRef,
};

/// Why reading, writing or running a vector failed.
#[derive(Debug, thiserror::Error)]
pub enum VectorError {
    /// The op refused its arguments or failed.
    #[error(transparent)]
    Op(#[from] crate::Error),
    /// A file or the manifest is not what the format or the spec says.
    #[error("test vector format: {0}")]
    Format(String),
    #[error(transparent)]
    Io(#[from] std::io::Error),
}

pub type Result<T> = std::result::Result<T, VectorError>;

fn format_err<T>(message: impl Into<String>) -> Result<T> {
    Err(VectorError::Format(message.into()))
}

/// The element data of a tensor.
#[derive(Clone, Debug, PartialEq)]
pub enum Data {
    F32(Vec<f32>),
    F64(Vec<f64>),
    I32(Vec<i32>),
}

impl Data {
    pub fn len(&self) -> usize {
        match self {
            Data::F32(x) => x.len(),
            Data::F64(x) => x.len(),
            Data::I32(x) => x.len(),
        }
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// The values as f64 (exact for every variant).
    pub fn to_f64(&self) -> Vec<f64> {
        match self {
            Data::F32(x) => x.iter().map(|&v| v as f64).collect(),
            Data::F64(x) => x.clone(),
            Data::I32(x) => x.iter().map(|&v| v as f64).collect(),
        }
    }
}

/// A named tensor of a vector: its shape and data.
#[derive(Clone, Debug, PartialEq)]
pub struct Tensor {
    pub shape: Vec<usize>,
    pub data: Data,
}

/// Tensors by name (sorted, so every serialisation is deterministic).
pub type Tensors = BTreeMap<String, Tensor>;
/// Dimension values by symbol (`"B"`, `"d"`, `"E"`, …).
pub type Dims = BTreeMap<String, usize>;

/// One test vector: an op at one size, with every tensor of [`Op::tensors`].
#[derive(Clone, Debug, PartialEq)]
pub struct Vector {
    pub op: Op,
    pub size: String,
    pub dims: Dims,
    pub tensors: Tensors,
}

impl Vector {
    /// The vector's file name, `<size>_<op>.safetensors`.
    pub fn file_name(&self) -> String {
        file_name(self.op, &self.size)
    }
}

pub fn file_name(op: Op, size: &str) -> String {
    format!("{size}_{}.safetensors", op.name())
}

/// `kernels/testvectors/` of this repository.
pub fn default_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../kernels/testvectors")
}

// ------------------------------------------------------------------------------------------------
// Running an op on named tensors (any backend, f32 or f64)
// ------------------------------------------------------------------------------------------------

fn get<'a>(t: &'a Tensors, name: &str) -> Result<&'a Tensor> {
    t.get(name)
        .map_or_else(|| format_err(format!("tensor {name} is missing")), Ok)
}

fn fref<'a>(t: &'a Tensors, name: &str) -> Result<TensorRef<'a>> {
    match &get(t, name)?.data {
        Data::F32(x) => Ok(TensorRef::F32(x)),
        Data::F64(x) => Ok(TensorRef::F64(x)),
        Data::I32(_) => format_err(format!("tensor {name} must be float, is int32")),
    }
}

fn iref<'a>(t: &'a Tensors, name: &str) -> Result<&'a [i32]> {
    match &get(t, name)?.data {
        Data::I32(x) => Ok(x),
        _ => format_err(format!("tensor {name} must be int32")),
    }
}

fn fmut(data: &mut Data) -> TensorMut<'_> {
    match data {
        Data::F32(x) => TensorMut::F32(x),
        Data::F64(x) => TensorMut::F64(x),
        Data::I32(_) => unreachable!("float outputs are allocated as F32 or F64"),
    }
}

/// The float type of a set of tensors (that of the first float tensor).
fn float_type(t: &Tensors) -> Result<DType> {
    for tensor in t.values() {
        match tensor.data {
            Data::F32(_) => return Ok(DType::F32),
            Data::F64(_) => return Ok(DType::F64),
            Data::I32(_) => {}
        }
    }
    format_err("no float tensor")
}

fn zeros(dtype: DType, len: usize) -> Data {
    match dtype {
        DType::F64 => Data::F64(vec![0.0; len]),
        _ => Data::F32(vec![0.0; len]),
    }
}

fn dim(dims: &Dims, symbol: &str) -> Result<usize> {
    dims.get(symbol)
        .copied()
        .map_or_else(|| format_err(format!("dimension {symbol} is missing")), Ok)
}

fn cell_dims(dims: &Dims) -> Result<CellDims> {
    Ok(CellDims {
        b: dim(dims, "B")?,
        n: dim(dims, "N")?,
        d: dim(dims, "d")?,
        k: dim(dims, "K")?,
    })
}

fn unit_dims(dims: &Dims) -> Result<UnitDims> {
    Ok(UnitDims {
        p: dim(dims, "P")?,
        m: dim(dims, "M")?,
        d: dim(dims, "d")?,
        h: dim(dims, "H")?,
    })
}

/// Allocate every tensor of `role` with its spec shape (float in `dtype`, int32 as zeros).
fn allocate(op: Op, role: Role, dims: &Dims, dtype: DType) -> Result<Tensors> {
    let mut out = Tensors::new();
    for spec in op.tensors().iter().filter(|t| t.role == role) {
        let shape = spec::resolve_shape(spec, dims)?;
        let len = shape.iter().product();
        let data = match spec.kind {
            Kind::Float => zeros(dtype, len),
            Kind::Int32 => Data::I32(vec![0; len]),
        };
        out.insert(spec.name.to_owned(), Tensor { shape, data });
    }
    Ok(out)
}

/// Take a tensor's data out of `t` (to hold several `&mut` at once).
fn take(t: &mut Tensors, name: &str) -> Data {
    std::mem::replace(
        &mut t.get_mut(name).expect("allocated above").data,
        Data::I32(Vec::new()),
    )
}

fn put(t: &mut Tensors, name: &str, data: Data) {
    t.get_mut(name).expect("allocated above").data = data;
}

/// Run the forward of `op` on `backend`: the tensors of role `Output`, computed from the `Input`
/// tensors of `t` (in their float type, f32 or f64).
pub fn forward(backend: &dyn Backend, op: Op, dims: &Dims, t: &Tensors) -> Result<Tensors> {
    let dtype = float_type(t)?;
    let mut out = allocate(op, Role::Output, dims, dtype)?;
    match op {
        Op::GatherConcat => {
            let mut v = take(&mut out, "v");
            backend.gather_concat(GatherConcat {
                u: fref(t, "u")?,
                eps: fref(t, "eps")?,
                h: fref(t, "h")?,
                m: fref(t, "m")?,
                cell_idx: iref(t, "cell_idx")?,
                v: fmut(&mut v),
                dims: cell_dims(dims)?,
            })?;
            put(&mut out, "v", v);
        }
        Op::GroupedUnitMlp => {
            let mut hidden = take(&mut out, "hidden_saved");
            let mut y = take(&mut out, "out");
            backend.grouped_unit_mlp_fwd(GroupedUnitMlpFwd {
                v: fref(t, "v")?,
                unit_idx: iref(t, "unit_idx")?,
                w1: fref(t, "W1")?,
                b1: fref(t, "b1")?,
                w2: fref(t, "W2")?,
                b2: fref(t, "b2")?,
                hidden_saved: fmut(&mut hidden),
                out: fmut(&mut y),
                dims: unit_dims(dims)?,
            })?;
            put(&mut out, "hidden_saved", hidden);
            put(&mut out, "out", y);
        }
        Op::CsrMessages => {
            let mut m = take(&mut out, "m");
            backend.csr_messages(CsrMessages {
                h: fref(t, "h")?,
                indptr: iref(t, "indptr")?,
                indices: iref(t, "indices")?,
                a: fref(t, "a")?,
                v_proj: fref(t, "V")?,
                cell_idx: iref(t, "cell_idx")?,
                m: fmut(&mut m),
                dims: cell_dims(dims)?,
                e: dim(dims, "E")?,
            })?;
            put(&mut out, "m", m);
        }
        Op::GatedDeltaUpdate => {
            // In place: start from copies of h, q and age.
            let mut h = get(t, "h")?.data.clone();
            let mut q = get(t, "q")?.data.clone();
            let mut age = iref(t, "age")?.to_vec();
            let mut saved = take(&mut out, "h_old_saved");
            backend.gated_delta_update(GatedDeltaUpdate {
                h: fmut(&mut h),
                q: fmut(&mut q),
                age: &mut age,
                cell_idx: iref(t, "cell_idx")?,
                valid: iref(t, "valid")?,
                c: fref(t, "c")?,
                b: fref(t, "b")?,
                h_old_saved: fmut(&mut saved),
                dims: cell_dims(dims)?,
            })?;
            put(&mut out, "h_out", h);
            put(&mut out, "q_out", q);
            put(&mut out, "age_out", Data::I32(age));
            put(&mut out, "h_old_saved", saved);
        }
    }
    Ok(out)
}

/// Run the backward of `op` on `backend`: the tensors of role `Grad`, from the inputs, the saved
/// forward outputs and the cotangents in `t`.
pub fn backward(backend: &dyn Backend, op: Op, dims: &Dims, t: &Tensors) -> Result<Tensors> {
    let dtype = float_type(t)?;
    let mut out = allocate(op, Role::Grad, dims, dtype)?;
    match op {
        Op::GatherConcat => {
            let (mut gu, mut ge) = (take(&mut out, "grad_u"), take(&mut out, "grad_eps"));
            let (mut gh, mut gm) = (take(&mut out, "grad_h"), take(&mut out, "grad_m"));
            backend.gather_concat_bwd(GatherConcatBwd {
                grad_v: fref(t, "grad_v")?,
                cell_idx: iref(t, "cell_idx")?,
                grad_u: fmut(&mut gu),
                grad_eps: fmut(&mut ge),
                grad_h: fmut(&mut gh),
                grad_m: fmut(&mut gm),
                dims: cell_dims(dims)?,
                deterministic: true,
            })?;
            put(&mut out, "grad_u", gu);
            put(&mut out, "grad_eps", ge);
            put(&mut out, "grad_h", gh);
            put(&mut out, "grad_m", gm);
        }
        Op::GroupedUnitMlp => {
            let mut gv = take(&mut out, "grad_v");
            let (mut gw1, mut gb1) = (take(&mut out, "grad_W1"), take(&mut out, "grad_b1"));
            let (mut gw2, mut gb2) = (take(&mut out, "grad_W2"), take(&mut out, "grad_b2"));
            backend.grouped_unit_mlp_bwd(GroupedUnitMlpBwd {
                v: fref(t, "v")?,
                unit_idx: iref(t, "unit_idx")?,
                w1: fref(t, "W1")?,
                w2: fref(t, "W2")?,
                hidden_saved: fref(t, "hidden_saved")?,
                grad_out: fref(t, "grad_out")?,
                grad_v: fmut(&mut gv),
                grad_w1: fmut(&mut gw1),
                grad_b1: fmut(&mut gb1),
                grad_w2: fmut(&mut gw2),
                grad_b2: fmut(&mut gb2),
                dims: unit_dims(dims)?,
                deterministic: true,
            })?;
            put(&mut out, "grad_v", gv);
            put(&mut out, "grad_W1", gw1);
            put(&mut out, "grad_b1", gb1);
            put(&mut out, "grad_W2", gw2);
            put(&mut out, "grad_b2", gb2);
        }
        Op::CsrMessages => {
            let (mut gh, mut ga) = (take(&mut out, "grad_h"), take(&mut out, "grad_a"));
            let mut gv = take(&mut out, "grad_V");
            backend.csr_messages_bwd(CsrMessagesBwd {
                h: fref(t, "h")?,
                indptr: iref(t, "indptr")?,
                indices: iref(t, "indices")?,
                a: fref(t, "a")?,
                v_proj: fref(t, "V")?,
                cell_idx: iref(t, "cell_idx")?,
                grad_m: fref(t, "grad_m")?,
                grad_h: fmut(&mut gh),
                grad_a: fmut(&mut ga),
                grad_v_proj: fmut(&mut gv),
                dims: cell_dims(dims)?,
                e: dim(dims, "E")?,
                deterministic: true,
            })?;
            put(&mut out, "grad_h", gh);
            put(&mut out, "grad_a", ga);
            put(&mut out, "grad_V", gv);
        }
        Op::GatedDeltaUpdate => {
            let (mut gh, mut gq) = (take(&mut out, "grad_h"), take(&mut out, "grad_q"));
            let (mut gc, mut gb) = (take(&mut out, "grad_c"), take(&mut out, "grad_b"));
            backend.gated_delta_update_bwd(GatedDeltaUpdateBwd {
                cell_idx: iref(t, "cell_idx")?,
                valid: iref(t, "valid")?,
                c: fref(t, "c")?,
                b: fref(t, "b")?,
                h_old_saved: fref(t, "h_old_saved")?,
                grad_h_out: fref(t, "grad_h_out")?,
                grad_q_out: fref(t, "grad_q_out")?,
                grad_h: fmut(&mut gh),
                grad_q: fmut(&mut gq),
                grad_c: fmut(&mut gc),
                grad_b: fmut(&mut gb),
                dims: cell_dims(dims)?,
            })?;
            put(&mut out, "grad_h", gh);
            put(&mut out, "grad_q", gq);
            put(&mut out, "grad_c", gc);
            put(&mut out, "grad_b", gb);
        }
    }
    Ok(out)
}

/// The tensors of `t` whose role is one of `roles`.
pub fn with_roles(op: Op, t: &Tensors, roles: &[Role]) -> Tensors {
    t.iter()
        .filter(|(name, _)| op.tensor(name).is_some_and(|s| roles.contains(&s.role)))
        .map(|(name, tensor)| (name.clone(), tensor.clone()))
        .collect()
}

/// `t` with every F32 tensor widened (exactly) to F64.
pub fn widen(t: &Tensors) -> Tensors {
    t.iter()
        .map(|(name, tensor)| {
            let data = match &tensor.data {
                Data::F32(x) => Data::F64(x.iter().map(|&v| v as f64).collect()),
                other => other.clone(),
            };
            (
                name.clone(),
                Tensor {
                    shape: tensor.shape.clone(),
                    data,
                },
            )
        })
        .collect()
}

/// `t` with every F64 tensor rounded (to nearest) to F32.
pub fn narrow(t: &Tensors) -> Tensors {
    t.iter()
        .map(|(name, tensor)| {
            let data = match &tensor.data {
                Data::F64(x) => Data::F32(x.iter().map(|&v| v as f32).collect()),
                other => other.clone(),
            };
            (
                name.clone(),
                Tensor {
                    shape: tensor.shape.clone(),
                    data,
                },
            )
        })
        .collect()
}

// ------------------------------------------------------------------------------------------------
// Generation
// ------------------------------------------------------------------------------------------------

/// SplitMix64 (Steele, Lea and Flood): a tiny, fully specified generator.
#[derive(Clone, Debug)]
pub struct SplitMix64(u64);

impl SplitMix64 {
    pub fn new(seed: u64) -> Self {
        SplitMix64(seed)
    }

    pub fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9e37_79b9_7f4a_7c15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
        z ^ (z >> 31)
    }

    /// An integer in `[0, n)` (modulo reduction: the bias is irrelevant here, the determinism is
    /// what matters).
    pub fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % n as u64) as usize
    }

    /// An integer in `[lo, hi]`.
    pub fn int_in(&mut self, lo: i64, hi: i64) -> i64 {
        lo + (self.next_u64() % (hi - lo + 1) as u64) as i64
    }

    /// Fisher-Yates shuffle.
    pub fn shuffle<T>(&mut self, x: &mut [T]) {
        for i in (1..x.len()).rev() {
            let j = self.below(i + 1);
            x.swap(i, j);
        }
    }
}

/// FNV-1a, 64 bit.
fn fnv1a(text: &str) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in text.bytes() {
        hash ^= byte as u64;
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

/// The seed of a vector's stream.
pub fn seed(op: Op, size: &Size) -> u64 {
    fnv1a(&format!("hsn-p2.9/{}/{}", size.name, op.name()))
}

/// `2^-e` exactly.
fn pow2_neg(e: u32) -> f32 {
    f32::from_bits((127 - e) << 23)
}

/// `k · 2^-(7+t)` with `k` uniform in [−128, 128]: values in `[−2^-t, 2^-t]`, exact in f16/bf16.
fn grid(rng: &mut SplitMix64, len: usize, t: u32) -> Vec<f32> {
    let scale = pow2_neg(7 + t);
    (0..len)
        .map(|_| rng.int_in(-128, 128) as f32 * scale)
        .collect()
}

/// `k / 256` with `k` uniform in `[lo, hi]`.
fn fraction(rng: &mut SplitMix64, len: usize, lo: i64, hi: i64) -> Vec<f32> {
    (0..len)
        .map(|_| rng.int_in(lo, hi) as f32 * pow2_neg(8))
        .collect()
}

/// The weight scale exponent `t` for fan-in `f`: the largest `t ≥ 0` with `2^t ≤ √f / 2`, so a
/// weight grid in `[−2^-t, 2^-t]` keeps pre-activations of order one.
fn fan_in_shift(f: usize) -> u32 {
    let mut t = 0;
    while 4 * 4usize.pow(t + 1) <= f {
        t += 1;
    }
    t
}

/// `count` distinct cells of `[0, n)`, none equal to `exclude`, in random order.
fn distinct_cells(
    rng: &mut SplitMix64,
    n: usize,
    count: usize,
    exclude: Option<usize>,
) -> Vec<usize> {
    let mut pool: Vec<usize> = (0..n).filter(|&i| Some(i) != exclude).collect();
    assert!(count <= pool.len(), "cannot draw {count} distinct cells");
    for i in 0..count {
        let j = i + rng.below(pool.len() - i);
        pool.swap(i, j);
    }
    pool.truncate(count);
    pool
}

/// `cell_idx [B, K]` with distinct cells per row; the last row repeats its first cell in its last
/// slot (repeats are allowed and real); `first` (if any) is forced into slot (0, 0).
fn cell_rows(rng: &mut SplitMix64, size: &Size, first: Option<usize>) -> Vec<i32> {
    let mut idx = Vec::with_capacity(size.b * size.k);
    for r in 0..size.b {
        let mut row = match first {
            Some(forced) if r == 0 => {
                let mut rest = distinct_cells(rng, size.n, size.k - 1, Some(forced));
                rest.insert(0, forced);
                rest
            }
            _ => distinct_cells(rng, size.n, size.k, None),
        };
        if r == size.b - 1 && size.k >= 2 {
            row[size.k - 1] = row[0];
        }
        idx.extend(row.into_iter().map(|c| c as i32));
    }
    idx
}

fn float(shape: Vec<usize>, x: Vec<f32>) -> Tensor {
    Tensor {
        shape,
        data: Data::F32(x),
    }
}

fn int(shape: Vec<usize>, x: Vec<i32>) -> Tensor {
    Tensor {
        shape,
        data: Data::I32(x),
    }
}

/// The in-degree of `cell` in the vector graph: every other cell at `tiny` (2), the A.1 value 4
/// at `ref`, and `cell mod 6` (0 to 5, with empty rows) at `odd`.
fn in_degree(size: &Size, cell: usize) -> usize {
    match size.name {
        "tiny" => size.n - 1,
        "odd" => cell % 6,
        _ => 4,
    }
}

/// The inputs and cotangents of a vector (f32 / i32) and its dimensions.
pub fn draw_inputs(op: Op, size: &Size) -> (Dims, Tensors) {
    let mut rng = SplitMix64::new(seed(op, size));
    let Size {
        b, n, d, k, m, h, ..
    } = *size;
    let p = size.p();
    let mut dims = Dims::new();
    let mut t = Tensors::new();
    let mut add = |name: &str, tensor: Tensor| {
        t.insert(name.to_owned(), tensor);
    };
    match op {
        Op::GatherConcat => {
            for (key, value) in [("B", b), ("N", n), ("d", d), ("K", k)] {
                dims.insert(key.to_owned(), value);
            }
            add("u", float(vec![b, d], grid(&mut rng, b * d, 0)));
            add("eps", float(vec![b, d], grid(&mut rng, b * d, 0)));
            add("h", float(vec![b, n, d], grid(&mut rng, b * n * d, 0)));
            add("m", float(vec![b, k, d], grid(&mut rng, b * k * d, 0)));
            add("cell_idx", int(vec![b, k], cell_rows(&mut rng, size, None)));
            add(
                "grad_v",
                float(vec![b, k, 4 * d], grid(&mut rng, b * k * 4 * d, 0)),
            );
        }
        Op::GroupedUnitMlp => {
            for (key, value) in [("P", p), ("M", m), ("d", d), ("H", h)] {
                dims.insert(key.to_owned(), value);
            }
            // Every unit has a pair, except unit 3 at `odd` (zero gradients for an absent unit).
            let present: Vec<i32> = (0..m as i32)
                .filter(|&j| !(size.name == "odd" && j == 3))
                .collect();
            let mut units: Vec<i32> = (0..p)
                .map(|i| {
                    if i < present.len() {
                        present[i]
                    } else {
                        present[rng.below(present.len())]
                    }
                })
                .collect();
            rng.shuffle(&mut units);
            add("v", float(vec![p, 4 * d], grid(&mut rng, p * 4 * d, 0)));
            add("unit_idx", int(vec![p], units));
            let len1 = m * 4 * d * h;
            add(
                "W1",
                float(vec![m, 4 * d, h], grid(&mut rng, len1, fan_in_shift(4 * d))),
            );
            add("b1", float(vec![m, h], grid(&mut rng, m * h, 2)));
            add(
                "W2",
                float(vec![m, h, d], grid(&mut rng, m * h * d, fan_in_shift(h))),
            );
            add("b2", float(vec![m, d], grid(&mut rng, m * d, 2)));
            add("grad_out", float(vec![p, d], grid(&mut rng, p * d, 0)));
        }
        Op::CsrMessages => {
            let mut indptr = vec![0i32];
            let mut indices = Vec::new();
            for cell in 0..n {
                let mut sources = distinct_cells(&mut rng, n, in_degree(size, cell), Some(cell));
                sources.sort_unstable();
                indices.extend(sources.into_iter().map(|j| j as i32));
                indptr.push(indices.len() as i32);
            }
            let e = indices.len();
            for (key, value) in [("B", b), ("N", n), ("d", d), ("K", k), ("E", e)] {
                dims.insert(key.to_owned(), value);
            }
            let empty_row = (0..n).find(|&cell| in_degree(size, cell) == 0);
            add("h", float(vec![b, n, d], grid(&mut rng, b * n * d, 0)));
            add("indptr", int(vec![n + 1], indptr));
            add("indices", int(vec![e], indices));
            add("a", float(vec![e], fraction(&mut rng, e, 13, 243)));
            add(
                "V",
                float(vec![d, d], grid(&mut rng, d * d, fan_in_shift(d))),
            );
            add(
                "cell_idx",
                int(vec![b, k], cell_rows(&mut rng, size, empty_row)),
            );
            add("grad_m", float(vec![b, k, d], grid(&mut rng, b * k * d, 0)));
        }
        Op::GatedDeltaUpdate => {
            for (key, value) in [("B", b), ("N", n), ("d", d), ("K", k)] {
                dims.insert(key.to_owned(), value);
            }
            // Row r has min(r, K−1) padded slots at its end, holding values that must never be
            // read: a duplicate of the row's first valid cell, −1, N and i32::MAX.
            let mut cell_idx = Vec::with_capacity(b * k);
            let mut valid = Vec::with_capacity(b * k);
            for r in 0..b {
                let padded = r.min(k - 1);
                let cells = distinct_cells(&mut rng, n, k - padded, None);
                let garbage = [cells[0] as i32, -1, n as i32, i32::MAX];
                for &cell in &cells {
                    cell_idx.push(cell as i32);
                    valid.push(1);
                }
                for ordinal in 0..padded {
                    cell_idx.push(garbage[(r - 1 + ordinal) % garbage.len()]);
                    valid.push(0);
                }
            }
            add("h", float(vec![b, n, d], grid(&mut rng, b * n * d, 0)));
            add("q", float(vec![b, d], grid(&mut rng, b * d, 0)));
            let age = (0..b * n).map(|_| rng.below(100) as i32).collect();
            add("age", int(vec![b, n], age));
            add("cell_idx", int(vec![b, k], cell_idx));
            add("valid", int(vec![b, k], valid));
            add("c", float(vec![b, k, d], grid(&mut rng, b * k * d, 0)));
            add(
                "b",
                float(vec![b, k, d], fraction(&mut rng, b * k * d, 1, 255)),
            );
            add(
                "grad_h_out",
                float(vec![b, n, d], grid(&mut rng, b * n * d, 0)),
            );
            add("grad_q_out", float(vec![b, d], grid(&mut rng, b * d, 0)));
        }
    }
    (dims, t)
}

/// The complete vector of `op` at `size`: drawn inputs and cotangents, then outputs and gradients
/// from the f64 oracle, rounded once to f32.
pub fn generate(op: Op, size: &Size) -> Result<Vector> {
    let (dims, inputs) = draw_inputs(op, size);
    let wide = widen(&inputs);
    let outputs = forward(&CpuBackend, op, &dims, &wide)?;
    let mut all = wide;
    all.extend(outputs.clone());
    let grads = backward(&CpuBackend, op, &dims, &all)?;
    let mut tensors = inputs;
    tensors.extend(narrow(&outputs));
    tensors.extend(narrow(&grads));
    Ok(Vector {
        op,
        size: size.name.to_owned(),
        dims,
        tensors,
    })
}

// ------------------------------------------------------------------------------------------------
// safetensors (the format: u64 LE header length, JSON header, raw little-endian data)
// ------------------------------------------------------------------------------------------------

/// The metadata keys every vector file carries.
const META_SPEC_VERSION: &str = "hsn_ops_spec_version";

/// The vector as safetensors bytes: tensors in name order, header padded with spaces to a
/// multiple of 8 bytes, `__metadata__` with the spec version, op, size and dimensions.
pub fn to_safetensors(v: &Vector) -> Result<Vec<u8>> {
    let mut header = serde_json::Map::new();
    let mut body: Vec<u8> = Vec::new();
    for (name, tensor) in &v.tensors {
        let start = body.len();
        let dtype = match &tensor.data {
            Data::F32(x) => {
                x.iter().for_each(|f| body.extend(f.to_le_bytes()));
                "F32"
            }
            Data::I32(x) => {
                x.iter().for_each(|i| body.extend(i.to_le_bytes()));
                "I32"
            }
            Data::F64(_) => return format_err(format!("{name}: vectors store f32, not f64")),
        };
        if tensor.shape.iter().product::<usize>() != tensor.data.len() {
            return format_err(format!(
                "{name}: shape {:?} does not match its data",
                tensor.shape
            ));
        }
        header.insert(
            name.clone(),
            json!({"dtype": dtype, "shape": tensor.shape, "data_offsets": [start, body.len()]}),
        );
    }
    let dims = serde_json::to_string(&v.dims).expect("a map of integers serialises");
    let mut meta = serde_json::Map::new();
    meta.insert(
        META_SPEC_VERSION.to_owned(),
        Value::from(SPEC_VERSION.to_string()),
    );
    meta.insert("op".to_owned(), Value::from(v.op.name()));
    meta.insert("size".to_owned(), Value::from(v.size.clone()));
    meta.insert("dims".to_owned(), Value::from(dims));
    header.insert("__metadata__".to_owned(), Value::Object(meta));
    let mut text = serde_json::to_string(&Value::Object(header)).expect("JSON serialises");
    while !(8 + text.len()).is_multiple_of(8) {
        text.push(' ');
    }
    let mut out = Vec::with_capacity(8 + text.len() + body.len());
    out.extend((text.len() as u64).to_le_bytes());
    out.extend(text.as_bytes());
    out.extend(body);
    Ok(out)
}

/// Parse a vector file, checking its spec version and every tensor against [`Op::tensors`]
/// (names, kinds, shapes); refuses anything else.
pub fn from_safetensors(bytes: &[u8]) -> Result<Vector> {
    if bytes.len() < 8 {
        return format_err("file shorter than its 8-byte header length");
    }
    let n = u64::from_le_bytes(bytes[..8].try_into().expect("8 bytes")) as usize;
    let Some(header_bytes) = bytes.get(8..8 + n) else {
        return format_err("header length beyond the end of the file");
    };
    let data = &bytes[8 + n..];
    let Value::Object(header) = serde_json::from_slice::<Value>(header_bytes)
        .map_err(|e| VectorError::Format(format!("header is not JSON: {e}")))?
    else {
        return format_err("header is not a JSON object");
    };
    let meta = header
        .get("__metadata__")
        .and_then(Value::as_object)
        .ok_or_else(|| VectorError::Format("no __metadata__".into()))?;
    let field = |key: &str| {
        meta.get(key)
            .and_then(Value::as_str)
            .ok_or_else(|| VectorError::Format(format!("__metadata__ has no {key}")))
    };
    if field(META_SPEC_VERSION)? != SPEC_VERSION.to_string() {
        return format_err(format!(
            "spec version {} in the file, {SPEC_VERSION} in this build",
            field(META_SPEC_VERSION)?
        ));
    }
    let op = Op::from_name(field("op")?)
        .ok_or_else(|| VectorError::Format(format!("unknown op {}", field("op").unwrap_or(""))))?;
    let size = field("size")?.to_owned();
    let dims: Dims = serde_json::from_str(field("dims")?)
        .map_err(|e| VectorError::Format(format!("dims: {e}")))?;
    let mut tensors = Tensors::new();
    for (name, info) in header.iter().filter(|(name, _)| *name != "__metadata__") {
        let Some(spec) = op.tensor(name) else {
            return format_err(format!("{} has no tensor {name}", op.name()));
        };
        let dtype = info.get("dtype").and_then(Value::as_str).unwrap_or("");
        let shape: Vec<usize> = info
            .get("shape")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(Value::as_u64)
                    .map(|x| x as usize)
                    .collect()
            })
            .unwrap_or_default();
        let offsets: Vec<usize> = info
            .get("data_offsets")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(Value::as_u64)
                    .map(|x| x as usize)
                    .collect()
            })
            .unwrap_or_default();
        let expected_shape = spec::resolve_shape(spec, &dims)?;
        if shape != expected_shape {
            return format_err(format!(
                "{name}: shape {shape:?}, the spec says {expected_shape:?}"
            ));
        }
        let expected_dtype = match spec.kind {
            Kind::Float => "F32",
            Kind::Int32 => "I32",
        };
        if dtype != expected_dtype {
            return format_err(format!(
                "{name}: dtype {dtype}, the spec says {expected_dtype}"
            ));
        }
        let len: usize = shape.iter().product();
        let [start, end] = offsets[..] else {
            return format_err(format!("{name}: bad data_offsets"));
        };
        let Some(raw) = data.get(start..end).filter(|raw| raw.len() == 4 * len) else {
            return format_err(format!(
                "{name}: data_offsets [{start}, {end}) do not hold {len} values"
            ));
        };
        let words = raw.as_chunks::<4>().0.iter().copied();
        let data = match spec.kind {
            Kind::Float => Data::F32(words.map(f32::from_le_bytes).collect()),
            Kind::Int32 => Data::I32(words.map(i32::from_le_bytes).collect()),
        };
        tensors.insert(name.clone(), Tensor { shape, data });
    }
    for spec in op.tensors() {
        if !tensors.contains_key(spec.name) {
            return format_err(format!("{} vector lacks tensor {}", op.name(), spec.name));
        }
    }
    Ok(Vector {
        op,
        size,
        dims,
        tensors,
    })
}

// ------------------------------------------------------------------------------------------------
// The manifest
// ------------------------------------------------------------------------------------------------

/// The manifest's file name.
pub const MANIFEST: &str = "MANIFEST.json";

/// One generated file: its vector and its bytes.
#[derive(Clone, Debug)]
pub struct VectorFile {
    pub vector: Vector,
    pub bytes: Vec<u8>,
}

/// Every vector (sizes in the chunk's order, ops in the header's order), serialised.
pub fn generate_all() -> Result<Vec<VectorFile>> {
    let mut files = Vec::new();
    for size in &spec::SIZES {
        for op in Op::ALL {
            let vector = generate(op, size)?;
            let bytes = to_safetensors(&vector)?;
            files.push(VectorFile { vector, bytes });
        }
    }
    Ok(files)
}

/// The manifest text for `files` (pretty JSON, sorted keys, trailing newline).
pub fn manifest(files: &[VectorFile]) -> String {
    let tol = |t: spec::Tolerance| json!({"atol": t.atol, "rtol": t.rtol});
    let sizes: serde_json::Map<String, Value> = spec::SIZES
        .iter()
        .map(|s| {
            let dims = json!({"B": s.b, "N": s.n, "d": s.d, "K": s.k, "M": s.m, "H": s.h});
            (s.name.to_owned(), dims)
        })
        .collect();
    let entries: Vec<Value> = files
        .iter()
        .map(|f| {
            json!({
                "path": f.vector.file_name(),
                "op": f.vector.op.name(),
                "size": f.vector.size,
                "dims": f.vector.dims,
                "bytes": f.bytes.len(),
                "sha256": hex(&sha256(&f.bytes)),
            })
        })
        .collect();
    let doc = json!({
        "spec_version": SPEC_VERSION,
        "generator": "rust/hsn-kernels/src/vectors.rs: inputs on an f16/bf16-exact grid from \
                      SplitMix64; outputs and gradients from the CPU oracle in f64, rounded once \
                      to f32",
        "regenerate": "HSN_WRITE_TESTVECTORS=1 cargo test -p hsn-kernels --test oracle \
                       vectors_regenerate_deterministically",
        "tolerances": {
            "f32": tol(spec::TOL_F32),
            "f16": tol(spec::TOL_F16),
            "bf16": tol(spec::TOL_BF16),
        },
        "sizes": sizes,
        "files": entries,
    });
    let mut text = serde_json::to_string_pretty(&doc).expect("JSON serialises");
    text.push('\n');
    text
}

/// Write every file of `files` and the manifest into `dir`.
pub fn write_all(dir: &Path, files: &[VectorFile]) -> Result<()> {
    std::fs::create_dir_all(dir)?;
    for f in files {
        std::fs::write(dir.join(f.vector.file_name()), &f.bytes)?;
    }
    std::fs::write(dir.join(MANIFEST), manifest(files))?;
    Ok(())
}

/// Read the vector of `op` at `size` from `dir`, after checking its byte count and SHA-256
/// against the manifest (for the parity tests of other backends).
pub fn load(dir: &Path, op: Op, size: &str) -> Result<Vector> {
    let text = std::fs::read_to_string(dir.join(MANIFEST))?;
    let doc: Value =
        serde_json::from_str(&text).map_err(|e| VectorError::Format(format!("{MANIFEST}: {e}")))?;
    if doc.get("spec_version").and_then(Value::as_u64) != Some(SPEC_VERSION as u64) {
        return format_err(format!("{MANIFEST} is not spec version {SPEC_VERSION}"));
    }
    let name = file_name(op, size);
    let entry = doc
        .get("files")
        .and_then(Value::as_array)
        .and_then(|files| {
            files
                .iter()
                .find(|f| f.get("path").and_then(Value::as_str) == Some(name.as_str()))
        })
        .ok_or_else(|| VectorError::Format(format!("{MANIFEST} does not list {name}")))?;
    let bytes = std::fs::read(dir.join(&name))?;
    let digest = hex(&sha256(&bytes));
    if entry.get("bytes").and_then(Value::as_u64) != Some(bytes.len() as u64)
        || entry.get("sha256").and_then(Value::as_str) != Some(digest.as_str())
    {
        return format_err(format!(
            "{name} does not match its manifest entry (sha256 {digest})"
        ));
    }
    let vector = from_safetensors(&bytes)?;
    if vector.op != op || vector.size != size {
        return format_err(format!(
            "{name} holds {} at {}",
            vector.op.name(),
            vector.size
        ));
    }
    Ok(vector)
}

// ------------------------------------------------------------------------------------------------
// SHA-256 (FIPS 180-4), for the manifest: the workspace has no sha2 crate and P2.9 adds no
// dependency. Python checks the same digests with hashlib.
// ------------------------------------------------------------------------------------------------

const SHA256_K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

/// The SHA-256 digest of `data`.
pub fn sha256(data: &[u8]) -> [u8; 32] {
    let mut state: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let mut message = data.to_vec();
    message.push(0x80);
    while message.len() % 64 != 56 {
        message.push(0);
    }
    message.extend(((data.len() as u64).wrapping_mul(8)).to_be_bytes());
    for block in message.as_chunks::<64>().0 {
        let mut w = [0u32; 64];
        for (i, word) in block.as_chunks::<4>().0.iter().enumerate() {
            w[i] = u32::from_be_bytes(*word);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut h] = state;
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ (!e & g);
            let t1 = h
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA256_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        for (s, x) in state.iter_mut().zip([a, b, c, d, e, f, g, h]) {
            *s = s.wrapping_add(x);
        }
    }
    let mut out = [0u8; 32];
    for (chunk, word) in out.as_chunks_mut::<4>().0.iter_mut().zip(state) {
        *chunk = word.to_be_bytes();
    }
    out
}

/// Lower-case hex.
pub fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_p2_9_sha256_fips_180_examples() {
        assert_eq!(
            hex(&sha256(b"")),
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
        assert_eq!(
            hex(&sha256(b"abc")),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
        assert_eq!(
            hex(&sha256(
                b"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"
            )),
            "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"
        );
        let million_a = vec![b'a'; 1_000_000];
        assert_eq!(
            hex(&sha256(&million_a)),
            "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0"
        );
    }

    #[test]
    fn test_p2_9_grid_values_are_exact_in_half_precision() {
        let mut rng = SplitMix64::new(7);
        for t in 0..4 {
            for x in grid(&mut rng, 1000, t) {
                // At most 8 significant bits and an exponent within f16's normal range.
                let bits = x.to_bits();
                assert_eq!(bits & 0xffff, 0, "{x} has more than 8 significant bits");
                assert!(
                    x == 0.0 || x.abs() >= 2f32.powi(-14),
                    "{x} is subnormal in f16"
                );
            }
        }
        assert_eq!(fan_in_shift(16), 1);
        assert_eq!(fan_in_shift(256), 3);
        assert_eq!(fan_in_shift(8), 0);
        assert_eq!(fan_in_shift(64), 2);
    }

    #[test]
    fn test_p2_9_safetensors_round_trip() {
        for op in Op::ALL {
            let vector = generate(op, &spec::TINY).expect("tiny vector");
            let bytes = to_safetensors(&vector).expect("serialises");
            assert_eq!(bytes.len() % 4, 0);
            assert_eq!(
                (8 + u64::from_le_bytes(bytes[..8].try_into().unwrap())) % 8,
                0
            );
            assert_eq!(from_safetensors(&bytes).expect("parses"), vector);
        }
    }
}
